/* ---------- Bootstrap stats & UI ---------- */
function init() {
  const pages = new Set(CHUNKS.map(c => c.doc + "-" + c.page)).size;
  document.getElementById("statDocs").textContent = "4 ไฟล์";
  document.getElementById("statChunks").textContent = CHUNKS.length + " ส่วน";
  document.getElementById("statDocCount").textContent = "หน้าเอกสาร: " + pages + " หน้า";

  // donut + legend by doc share
  const counts = {};
  CHUNKS.forEach(c => counts[c.doc] = (counts[c.doc]||0) + 1);
  const total = CHUNKS.length;
  let gradParts = [], acc = 0, legendHtml = "";
  Object.keys(DOC_META).forEach(code => {
    const n = counts[code] || 0;
    const pct = total ? (n/total*100) : 0;
    const start = acc, end = acc + pct;
    gradParts.push(`${DOC_META[code].color} ${start}% ${end}%`);
    acc = end;
    legendHtml += `<div class="legend-item"><span class="legend-color" style="background:${DOC_META[code].color}"></span>${code} — ${pct.toFixed(0)}%</div>`;
  });
  document.getElementById("donutChart").style.background = `conic-gradient(${gradParts.join(",")})`;
  document.getElementById("donutLegend").innerHTML = legendHtml;

  // FAQ list
  document.getElementById("faqList").innerHTML = FAQS.map(q =>
    `<div class="faq-item" onclick="useQuestion(this)"><span>› ${q}</span></div>`
  ).join("");

  // Docs page grid
  const docStats = {};
  CHUNKS.forEach(c => {
    if (!docStats[c.doc]) docStats[c.doc] = { pages: new Set(), name: c.docName, chunks: 0 };
    docStats[c.doc].pages.add(c.page);
    docStats[c.doc].chunks++;
  });
  let docHtml = "";
  Object.keys(docStats).forEach(code => {
    const d = docStats[code];
    docHtml += `<div class="doc-card">
      <span class="doc-code" style="background:${DOC_META[code].color}22;color:${DOC_META[code].color}">${code}</span>
      <h4>${d.name}</h4>
      <div class="doc-meta">จำนวนหน้า: ${d.pages.size} หน้า &nbsp;•&nbsp; ส่วนข้อมูลที่จัดทำดัชนี: ${d.chunks}</div>
    </div>`;
  });
  document.getElementById("docGrid").innerHTML = docHtml;
}

/* ---------- Language & Cross-Lingual Search Dictionary ---------- */
function detectLanguage(text) {
  if (!text) return 'th';
  if (/[\u4E00-\u9FFF]/.test(text)) return 'zh';
  if (/[\u0E00-\u0E7F]/.test(text)) return 'th';
  if (/[a-zA-Z]/.test(text)) return 'en';
  return 'th';
}

function normalizeThai(str) {
  if (!str) return '';
  return str.replace(/[\u0E31\u0E34-\u0E3A\u0E47-\u0E4E]/g, '').toLowerCase();
}

