function expandQuery(query) {
  const lower = query.toLowerCase();
  const terms = [lower];
  for (const [key, thValues] of Object.entries(EN_TH_KEYWORDS)) {
    let matched = false;
    if (/[\u4E00-\u9FFF]/.test(key)) {
      matched = lower.includes(key);
    } else {
      matched = new RegExp('\\b' + key + '\\b', 'i').test(lower);
    }
    if (matched) {
      thValues.forEach(v => terms.push(v));
    }
  }
  return terms;
}

/* ---------- Retrieval: simple client-side keyword scoring over real text ---------- */
function scoreChunk(query, chunkText) {
  const q = query.trim();
  if (!q) return 0;
  const lowerQ = q.toLowerCase();
  const lowerText = chunkText.toLowerCase();
  let score = 0;
  
  if (lowerText.includes(lowerQ)) score += 70;

  const normQ = normalizeThai(q);
  const normText = normalizeThai(chunkText);
  if (normQ.length >= 4 && normText.includes(normQ)) score += 40;

  const grams = (len) => {
    for (let i = 0; i + len <= lowerQ.length; i++) {
      const g = lowerQ.slice(i, i + len);
      if (g.trim().length < len) continue;
      if (lowerText.includes(g)) score += len;
    }
  };
  grams(8); grams(6); grams(4);
  if (/[\u4E00-\u9FFF]/.test(lowerQ)) {
    grams(3); grams(2);
  }

  // Token matching for words
  const tokens = lowerQ.split(/[\s,?.!/]+/).filter(t => t.length >= 2);
  tokens.forEach(t => {
    if (lowerText.includes(t)) score += 12;
  });

  // Cross-lingual keyword expansion for Thai docs
  const expanded = expandQuery(q);
  expanded.slice(1).forEach(thTerm => {
    if (chunkText.includes(thTerm)) {
      score += 35;
    } else {
      const normTh = normalizeThai(thTerm);
      if (normTh.length >= 3 && normText.includes(normTh)) {
        score += 25;
      }
    }
  });

  return score;
}

function docBoost(query, doc) {
  const lower = query.toLowerCase();
  let boost = 0;
  if (doc === "DSBA" && (lower.includes("dsba") || lower.includes("วิทยาการข้อมูล") || lower.includes("data science") || lower.includes("business analytics") || lower.includes("数据科学") || lower.includes("商业分析"))) boost += 35;
  if (doc === "AIT" && (lower.includes("ait") || lower.includes("ปัญญาประดิษฐ์") || lower.includes("artificial intelligence") || lower.includes("ai ") || lower.includes("人工智能"))) boost += 35;
  if (doc === "IT-INTER" && (lower.includes("inter") || lower.includes("นานาชาติ") || lower.includes("international") || lower.includes("ธุรกิจ") || lower.includes("global") || lower.includes("国际"))) boost += 30;
  if (doc === "IT" && (/(^|[^a-z])it([^a-z]|$)/.test(lower) || lower.includes("信息技术")) && !lower.includes("inter") && !lower.includes("国际")) boost += 20;
  return boost;
}

function retrieve(query, k, sourceChunks = CHUNKS) {
  const scored = sourceChunks.map(c => ({
    c, s: scoreChunk(query, c.text) + docBoost(query, c.doc)
  })).filter(x => x.s > 0);
  scored.sort((a, b) => b.s - a.s);
  // light diversity: avoid >3 chunks from the exact same page run
  const picked = [], seenPages = {};
  for (const x of scored) {
    const key = x.c.doc + "-" + x.c.page;
    seenPages[key] = (seenPages[key] || 0) + 1;
    if (seenPages[key] > 2) continue;
    picked.push(x.c);
    if (picked.length >= k) break;
  }
  return picked;
}

