const getThaiError = (code) => {
  switch (code) {
    case 'auth/weak-password': return 'รหัสผ่านต้องมีความยาวอย่างน้อย 6 ตัวอักษร';
    case 'auth/email-already-in-use': return 'อีเมลนี้ถูกใช้งานแล้ว';
    case 'auth/user-not-found':
    case 'auth/wrong-password':
    case 'auth/invalid-credential':
      return 'อีเมลหรือรหัสผ่านไม่ถูกต้อง';
    case 'auth/invalid-email': return 'รูปแบบอีเมลไม่ถูกต้อง';
    default: return 'เกิดข้อผิดพลาด: ' + code;
  }
};

window.handleLogin = async function(e) {
  if (e) e.preventDefault();
  const email = document.getElementById("loginEmail").value;
  const password = document.getElementById("loginPassword").value;
  const errDiv = document.getElementById("loginError");
  const btn = document.getElementById("loginBtn");
  if (!email || !password) { errDiv.textContent = "กรุณากรอกอีเมลและรหัสผ่านให้ครบ"; return; }
  
  try {
    btn.textContent = "กำลังเข้าสู่ระบบ...";
    await signInWithEmailAndPassword(auth, email, password);
    errDiv.textContent = "";
  } catch (error) {
    errDiv.textContent = getThaiError(error.code);
    const row = document.getElementById('loginEmailRow');
    if (row) { row.classList.add('shake', 'invalid'); setTimeout(() => row.classList.remove('shake'), 400); }
  } finally {
    btn.textContent = "เข้าสู่ระบบ";
  }
}

window.handleRegister = async function(e) {
  if (e) e.preventDefault();
  const email = document.getElementById("regEmail").value;
  const password = document.getElementById("regPassword").value;
  const confirm = document.getElementById("regConfirm").value;
  const errDiv = document.getElementById("regError");
  const btn = document.getElementById("registerBtn");
  
  if (!email || !password) { errDiv.textContent = "กรุณากรอกอีเมลและรหัสผ่านให้ครบ"; return; }
  
  const passOk = window.evaluateChecklist ? window.evaluateChecklist(true) : (password.length >= 6);
  if (!passOk) { errDiv.textContent = "รหัสผ่านไม่ผ่านเงื่อนไขที่กำหนด"; return; }
  
  if (password !== confirm) {
    errDiv.textContent = "รหัสผ่านไม่ตรงกัน";
    const row = document.getElementById('regConfirmRow');
    if (row) { row.classList.add('shake', 'invalid'); setTimeout(() => row.classList.remove('shake'), 400); }
    return;
  }
  
  try {
    btn.textContent = "กำลังสมัครสมาชิก...";
    await createUserWithEmailAndPassword(auth, email, password);
    errDiv.textContent = "";
    showToast("สมัครสมาชิกสำเร็จ!");
  } catch (error) {
    errDiv.textContent = getThaiError(error.code);
    const row = document.getElementById('regEmailRow');
    if (row) { row.classList.add('shake', 'invalid'); setTimeout(() => row.classList.remove('shake'), 400); }
  } finally {
    btn.textContent = "สมัครสมาชิกใหม่";
  }
}

window.handleLogout = async function() {
  try {
    await signOut(auth);
    showToast("ออกจากระบบสำเร็จ");
  } catch (error) {
    console.error(error);
  }
}

async function saveHistoryToDB(question, timeStr) {
  try {
      let localHist = JSON.parse(localStorage.getItem('datalens_history')) || [];
      localHist.push({
          query: question,
          timestamp: Date.now(),
          resultsCount: 'หลาย'
      });
      if (localHist.length > 50) localHist.shift();
      localStorage.setItem('datalens_history', JSON.stringify(localHist));
  } catch(e) {}

  if (typeof currentUser === 'undefined' || !currentUser || typeof db === 'undefined' || !db) return;
  try {
    await addDoc(collection(db, "users", currentUser.uid, "history"), {
      question: question,
      time: timeStr,
      timestamp: new Date()
    });
  } catch (e) {
    console.error("Error saving history:", e);
  }
}

async function loadHistoryFromDB() {
  if (!currentUser || !db) return;
  try {
    const q = query(collection(db, "users", currentUser.uid, "history"), orderBy("timestamp", "desc"), limit(6));
    const querySnapshot = await getDocs(q);
    historyItems = [];
    querySnapshot.forEach((doc) => {
      const data = doc.data();
      historyItems.push({ q: data.question, t: data.time });
    });
    renderHistory();
  } catch (e) {
    console.error("Error loading history:", e);
  }
}

function renderHistory() {
  document.getElementById("historyList").innerHTML = historyItems.map(h =>
    `<div class="history-item" onclick="document.getElementById('questionInput').value=${JSON.stringify(h.q)}">
      <div class="history-icon">◷</div>
      <div><div class="history-question">${escapeHtml(h.q.slice(0,40))}${h.q.length>40?"...":""}</div><div class="history-time">${h.t} น.</div></div>
    </div>`
  ).join("");
}

